"""Copy only a new, complete ZIP generated by the official Even export."""
import json
import os
import re
import shutil
import stat
import subprocess
import sys
import tempfile
import time
import zipfile
from pathlib import Path

CACHE = Path.home() / "Library/Containers/com.even.sg/Data/Library/Caches"
RECEPTION = Path.home() / "Library/Application Support/R1 Bridge/Reception"
UUID = re.compile(r"[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}", re.I)
ZIP = re.compile(r"Even_health_data_[0-9]{8}\.zip", re.I)


def exports():
    for attempt in range(3):
        try:
            return scan_exports()
        except InterruptedError:
            if attempt == 2:
                raise
            time.sleep(0.2)


def scan_exports():
    result = {}
    # scandir reports permission errors instead of treating a denied directory as empty.
    with os.scandir(CACHE) as dirs:
        for folder in dirs:
            if not UUID.fullmatch(folder.name) or not folder.is_dir(follow_symlinks=False):
                continue
            try:
                with os.scandir(folder.path) as files:
                    for file in files:
                        if ZIP.fullmatch(file.name) and file.is_file(follow_symlinks=False):
                            item = file.stat(follow_symlinks=False)
                            result[folder.name + "/" + file.name] = [
                                item.st_ino, item.st_size, item.st_mtime_ns]
            except FileNotFoundError:
                continue
    return result


def finished_copy(relative, signature):
    src = CACHE / relative
    with tempfile.NamedTemporaryFile(dir=RECEPTION, prefix=".even-", delete=False) as tmp:
        temp = Path(tmp.name)
    try:
        with src.open("rb") as f, temp.open("wb") as dest:
            st = os.fstat(f.fileno())
            if not stat.S_ISREG(st.st_mode) or [st.st_ino, st.st_size, st.st_mtime_ns] != signature:
                return False
            shutil.copyfileobj(f, dest)
            dest.flush()
            os.fsync(dest.fileno())
        if exports().get(relative) != signature or temp.stat().st_size != signature[1]:
            return False
        with zipfile.ZipFile(temp) as archive:
            if not any(Path(n).name.casefold() == "sleep.csv" for n in archive.namelist()):
                return False
            if archive.testzip() is not None:
                return False
        temp.replace(RECEPTION / (temp.name.removeprefix(".") + ".zip"))
        return True
    except (FileNotFoundError, EOFError, zipfile.BadZipFile):
        return False
    finally:
        temp.unlink(missing_ok=True)


def capture_cards():
    # Les cartes sont un complément. Un écran indisponible ne doit pas perdre le ZIP.
    helper = Path(__file__).with_name("cartes_even")
    try:
        process = subprocess.run([str(helper), "--capture"], stdout=subprocess.PIPE,
                                 stderr=subprocess.DEVNULL, timeout=32)
        known = {"CARDS_OK", "CARDS_PARTIAL", "CARDS_UNREADABLE", "CARDS_EVEN_UNAVAILABLE",
                 "CARDS_NAVIGATION", "CARDS_STORAGE", "CARDS_SESSION", "CARDS_ACCESSIBILITY"}
        label = process.stdout.decode("ascii", errors="ignore").strip()
        status = label if label in known else "CARDS_UNAVAILABLE"
    except (OSError, subprocess.TimeoutExpired):
        status = "CARDS_UNAVAILABLE"
    if status in {"CARDS_OK", "CARDS_PARTIAL"}:
        try:
            history = subprocess.run(
                ["/usr/bin/python3", "-B", str(RECEPTION.parent / "rapport_even.py"), "--enregistrer"],
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=12)
            if history.returncode:
                status = "CARDS_HISTORY_ERROR"
        except (OSError, subprocess.TimeoutExpired):
            status = "CARDS_HISTORY_ERROR"
    # Aucune valeur de mesure ni information de compte dans le suivi technique.
    try:
        with tempfile.NamedTemporaryFile(dir=RECEPTION.parent, mode="w", delete=False) as out:
            out.write(status + "\n")
        Path(out.name).replace(RECEPTION.parent / "etat_cartes.txt")
    except OSError:
        pass


def run(mode, manifest):
    os.umask(0o077)
    if mode == "avant":
        with manifest.open("x", encoding="utf-8") as out:
            json.dump(exports(), out)
        return 0
    if mode != "recuperer":
        return 64
    before = json.loads(manifest.read_text(encoding="utf-8"))
    deadline = time.monotonic() + 110
    while time.monotonic() < deadline:
        current = exports()
        for name, signature in sorted(current.items(), key=lambda entry: entry[1][2], reverse=True):
            if before.get(name) != signature and signature[1] and finished_copy(name, signature):
                capture_cards()
                return 0
        time.sleep(0.6)
    return 75


if __name__ == "__main__":
    try:
        sys.exit(run(sys.argv[1], Path(sys.argv[2])))
    except PermissionError:
        sys.exit(77)
    except (OSError, ValueError, IndexError):
        sys.exit(74)
